import { prisma } from '@/lib/prisma'
import { getCollection, COLLECTIONS } from '@/lib/mongodb'
import { BalanceTransaction } from '@/lib/types/mongodb'

export async function getBalance(memberId: string): Promise<number> {
  const member = await prisma.member.findUnique({
    where: { id: memberId },
    select: { balance: true },
  })
  return member?.balance || 0
}

export async function addTokens(
  memberId: string,
  amount: number,
  type: BalanceTransaction['type'],
  description: string
): Promise<number> {
  // Use Prisma transaction for atomic update
  const result = await prisma.$transaction(async (tx) => {
    // Get current balance
    const member = await tx.member.findUnique({
      where: { id: memberId },
      select: { balance: true },
    })

    if (!member) {
      throw new Error('Member not found')
    }

    const balanceBefore = member.balance
    const balanceAfter = balanceBefore + amount

    // Update balance
    await tx.member.update({
      where: { id: memberId },
      data: { balance: balanceAfter },
    })

    // Log transaction to MongoDB
    const balanceTransactions = await getCollection(COLLECTIONS.BALANCE_TRANSACTIONS)
    await balanceTransactions.insertOne({
      memberId,
      amount,
      type,
      description,
      balanceBefore,
      balanceAfter,
      createdAt: new Date(),
    })

    return balanceAfter
  })

  return result
}

export async function deductTokens(
  memberId: string,
  amount: number,
  type: BalanceTransaction['type'],
  description: string
): Promise<number> {
  // Use Prisma transaction for atomic update
  const result = await prisma.$transaction(async (tx) => {
    // Get current balance
    const member = await tx.member.findUnique({
      where: { id: memberId },
      select: { balance: true },
    })

    if (!member) {
      throw new Error('Member not found')
    }

    const balanceBefore = member.balance

    if (balanceBefore < amount) {
      throw new Error('Insufficient balance')
    }

    const balanceAfter = balanceBefore - amount

    // Update balance
    await tx.member.update({
      where: { id: memberId },
      data: { balance: balanceAfter },
    })

    // Log transaction to MongoDB
    const balanceTransactions = await getCollection(COLLECTIONS.BALANCE_TRANSACTIONS)
    await balanceTransactions.insertOne({
      memberId,
      amount: -amount,
      type,
      description,
      balanceBefore,
      balanceAfter,
      createdAt: new Date(),
    })

    return balanceAfter
  })

  return result
}

export async function getBalanceHistory(
  memberId: string,
  limit: number = 50
): Promise<BalanceTransaction[]> {
  const balanceTransactions = await getCollection(COLLECTIONS.BALANCE_TRANSACTIONS)
  const transactions = await balanceTransactions
    .find({ memberId })
    .sort({ createdAt: -1 })
    .limit(limit)
    .toArray()

  return transactions as unknown as BalanceTransaction[]
}

export async function hasInsufficientBalance(
  memberId: string,
  requiredAmount: number
): Promise<boolean> {
  const balance = await getBalance(memberId)
  return balance < requiredAmount
}

